INSERT INTO activity (id,title,type,start_time,end_time,location,description,status,create_time,update_time) VALUES ('ACT-2026-RECENT-001','联合国教科文组织第21届非遗大会','交流','2026-11-30 00:00:00','2026-12-05 23:59:59','福建省厦门市','2026年11月30日至12月5日，联合国教科文组织保护非物质文化遗产政府间委员会第21届常会将在福建省厦门市举办。这是联合国教科文组织非遗大会首次在我国举办。\n\n本届大会会徽“一鹭高飞”将厦门英文名称首字母X化为展翅白鹭，融合中国书法、篆刻、剪纸等非遗元素，以及日光岩、双子塔等厦门地标，表达文脉永续、交流互鉴的愿景。会徽将应用于大会开幕式、委员会全体会议、论坛、边会、文化活动及“中国时刻”系列演出等官方活动场景。\n\n本站提供公开活动资讯与来源阅读入口，不代办会议注册，也不代表主办方开放公众报名。参会资格、具体场地、日程和配套文化活动，以大会后续官方公告为准。\n\n公开来源：中国非物质文化遗产网 · 人民网\nhttps://www.ihchina.cn/news_details/31673.html\n日期按公开报道记录，未公布具体开放时刻；实际开放/入场安排请查阅来源。',1,'2026-11-10 19:10:00','2026-11-10 19:10:00') ON DUPLICATE KEY UPDATE id=id;
