INSERT INTO activity (id,title,type,start_time,end_time,location,description,status,create_time,update_time) VALUES ('ACT-2026-RECENT-002','守望——廊桥保护三年行动成果展','展览','2026-08-07 00:00:00','2026-11-07 23:59:59','北京市 · 中国工艺美术馆（中国非物质文化遗产馆）','“守望——廊桥保护三年行动成果展”于2026年8月7日在北京中国工艺美术馆（中国非物质文化遗产馆）开展，由文化和旅游部、国家文物局共同主办，展览持续至11月7日。\n\n展览以廊桥文化遗产系统性保护为主线，汇集廊桥分布省区共35座廊桥的实物模型、建筑构件、营造工具、图纸书籍等，系统呈现廊桥文化遗产及保护行动的历程、举措与成果。观众可以由构件、工具与记录资料，理解廊桥建筑背后的营造知识和保护实践。\n\n展厅邀请“中国木拱桥传统营造技艺”代表性传承人搭建局部实体廊桥，以沉浸式空间让观众近距离感受传统营造。本站以活动回顾方式收录，展期已结束；后续展览安排请以场馆公告为准。\n\n公开来源：中国非物质文化遗产网 · 新华社\nhttps://www.ihchina.cn/news_details/31643.html\n日期按公开报道记录，未公布具体开放时刻；实际开放/入场安排请查阅来源。',3,'2026-11-10 19:09:00','2026-11-10 19:10:00') ON DUPLICATE KEY UPDATE id=id;
