INSERT INTO activity (id,title,type,start_time,end_time,location,description,status,create_time,update_time) VALUES ('ACT-2026-RECENT-003','“可以观”非遗社教演艺活动','展演','2026-08-19 00:00:00','2026-08-23 23:59:59','北京市 · 中国非物质文化遗产馆','中国非物质文化遗产馆于2026年七夕推出“可以观”非遗社教演艺活动，首轮演出持续至8月23日。活动以四季时序为创作脉络，设置《春·茶》《夏·瓷》《秋·染》《冬·年》四季篇章，融合诗、书、印、琴、舞、音、歌等多元艺术，串联中国剪纸、龙泉青瓷烧制技艺等20余项非遗代表性项目。\n\n演出以老匠守艺、少年传艺的双线叙事，在开放、沉浸式演艺空间中重塑观演关系，让观众从“看物”走向“见人、见物、见生活”。参与团队包括非遗传承人、职高学生和经过免费培训的青少年，以本色演绎展现传承温度。\n\n馆内还联动“可以群”非遗研讨与市集、“可以游”馆外非遗研学，连接舞台欣赏、手工体验与在地探索。本站收录为首轮活动回顾，后续场次、票务和预约方式以场馆官方公告为准。\n\n公开来源：中国非物质文化遗产网 · 中国文化报\nhttps://www.ihchina.cn/news_details/31653.html\n日期按公开报道记录，未公布具体开放时刻；实际开放/入场安排请查阅来源。',3,'2026-11-10 19:08:00','2026-11-10 19:10:00') ON DUPLICATE KEY UPDATE id=id;
