INSERT INTO activity (id,title,type,start_time,end_time,location,description,status,create_time,update_time) VALUES ('ACT-2026-RECENT-004','艺“数”共生·云间揽粹——国际传统艺术邀请展松江巡展','展览','2026-08-18 00:00:00','2026-09-03 23:59:59','上海市松江区 · 云间会堂文化艺术中心','2026年8月18日，第十六届国际传统艺术邀请展·松江巡展暨顾绣列入国家级非遗名录20周年特展在上海松江云间会堂文化艺术中心开幕，展览持续至9月3日。\n\n展览汇集30余个国家和地区约120件艺术作品，其中国际展品75件、松江本土作品45件，涵盖绘画、雕塑、陶瓷、漆艺、刺绣、装置、综合材料及数字艺术。顾绣专题展区陈列20件精品，展现“画绣相融”、以针代笔的艺术特色。\n\n现场同步展示松江棉布纺织技艺、丝网版画、顾绣等本土项目，将传统技艺示范与作品展陈相结合。巡展由上海艺术品博物馆、松江区文化和旅游局、上海工艺美术职业学院、上海市非物质文化遗产保护中心联合主办。本站以活动回顾方式收录；新的巡展信息以主办方公告为准。\n\n公开来源：中国非物质文化遗产网 · 文旅中国客户端\nhttps://www.ihchina.cn/news2_details/31650.html\n日期按公开报道记录，未公布具体开放时刻；实际开放/入场安排请查阅来源。',3,'2026-11-10 19:07:00','2026-11-10 19:10:00') ON DUPLICATE KEY UPDATE id=id;
