INSERT INTO activity (id,title,type,start_time,end_time,location,description,status,create_time,update_time) VALUES ('ACT-2026-RECENT-005','觅巧寻缘——2026年节庆“叹”非遗七夕体验活动','培训','2026-08-19 00:00:00','2026-08-19 23:59:59','广东省广州市 · 广东省非物质文化遗产馆','2026年8月19日，广东省非物质文化遗产馆举办“觅巧寻缘”非遗体验活动，围绕七夕节俗连接非遗手作、共同创作与情感交流。活动邀请通草画绘制技艺、背带绣花技艺、广州珐琅制作技艺、七夕节（天河乞巧习俗）、丹霞红豆饰品制作技艺等项目的传承人参与。\n\n“通草寄情·鹊桥相会”共创区提供手绘、印章拓印与印画结合三种方式，参与者完成红嘴蓝鹊后，将作品拼入长卷，让个人创作成为集体记忆。其他体验包含乞巧《蝶恋花》制作、红豆手链串制、背带绣花与掐丝点蓝，照顾不同基础参与者的节奏。\n\n现场还设置明信片祝福交换等交流环节，使古老节俗与当代生活相连。本条记录为七夕当日活动回顾，不提供往期活动报名。后续节庆体验的场次、预约和收费信息，请查阅场馆官方公告。\n\n公开来源：中国非物质文化遗产网 · 广东非遗\nhttps://www.ihchina.cn/news2_details/31651.html\n日期按公开报道记录，未公布具体开放时刻；实际开放/入场安排请查阅来源。',3,'2026-11-10 19:06:00','2026-11-10 19:10:00') ON DUPLICATE KEY UPDATE id=id;
