INSERT INTO activity (id,title,type,start_time,end_time,location,description,status,create_time,update_time) VALUES ('ACT-2026-RECENT-006','2026内蒙古自治区非遗那达慕暨巴林右旗第25届那达慕','展演','2026-08-16 00:00:00','2026-08-18 23:59:59','内蒙古自治区赤峰市巴林右旗','2026年8月16日至18日，2026内蒙古自治区非遗那达慕暨巴林右旗第25届那达慕在赤峰市巴林右旗举行，以“欢乐草原·非遗那达慕”为主题，集中展示各民族交往交流交融的文化成果。\n\n活动设置开幕式、传统民俗赛事、全区非遗展示展销、巴林石文化周、多元非遗展演五大板块，将120余项非遗代表性项目带入草原会场。观众可近距离认识毡绣、奶食制作、剪纸、树皮画等手工技艺，感受安代舞、长调、好来宝等艺术表达，也能通过搏克、赛马、射箭等传统竞技理解那达慕文化。\n\n展演、展示、展销与体验一体化的组织方式，使非遗回到可感知的生活场景。本条收录为活动回顾。封面为本站设计的活动主题视觉，不是活动现场摄影；实际现场情况与后续活动安排，以来源报道及当地官方公告为准。\n\n公开来源：中国非物质文化遗产网 · 中国新闻网\nhttps://www.ihchina.cn/news2_details/31646.html\n日期按公开报道记录，未公布具体开放时刻；实际开放/入场安排请查阅来源。',3,'2026-11-10 19:05:00','2026-11-10 19:10:00') ON DUPLICATE KEY UPDATE id=id;
